// Differential probe for the pinned examples/jsm/math ports:
// examples/jsm/math/ImprovedNoise.js, ColorConverter.js, Capsule.js and OBB.js.
//
// Protocol: one scenario per stdin line, tokens separated by spaces. The scenario list is
// generated by compare-addon-math.mjs, which replays the same calls against the pinned
// three.js modules, so the field order below is the single source of truth for both sides.
//
//   noise <x> <y> <z>
//   hsv <h> <s> <v>
//   gethsv <r> <g> <b>
//   hsvrt <h> <s> <v>
//   hsl <h> <s> <l>
//   gethsl <r> <g> <b>
//   hslrt <h> <s> <l>
//   capsule-default
//   capsule <start3> <end3> <radius> <offset3>
//   capsule-box <start3> <end3> <radius> <min3> <max3>
//   obb-default
//   obb <center3> <halfSize3> <rotation9>
//   obb-apply <center3> <halfSize3> <rotation9> <matrix16>
//   obb-contains <center3> <halfSize3> <rotation9> <point3>
//   obb-clamp <center3> <halfSize3> <rotation9> <point3>
//   obb-box3 <center3> <halfSize3> <rotation9> <min3> <max3>
//   obb-sphere <center3> <halfSize3> <rotation9> <sphereCenter3> <radius>
//   obb-ray <center3> <halfSize3> <rotation9> <origin3> <direction3>
//   obb-obb <center3> <halfSize3> <rotation9> <center3> <halfSize3> <rotation9> [epsilon]
//   obb-plane <center3> <halfSize3> <rotation9> <normal3> <constant>
//   obb-frombox <min3> <max3>
//   obb-equals <center3> <halfSize3> <rotation9> <center3> <halfSize3> <rotation9>
//
// Rotation and matrix tokens are the storage order of `Matrix3.elements` /
// `Matrix4.elements`, so the generator can build the matrix with any upstream helper and
// hand over the exact doubles. Numbers use the shared encoding of the other probes: NaN,
// -0, Infinity and -Infinity travel as those four strings.
#include "core/JsonValue.h"
#include "math/Box3.h"
#include "math/Capsule.h"
#include "math/Color.h"
#include "math/ColorConverter.h"
#include "math/ImprovedNoise.h"
#include "math/Matrix3.h"
#include "math/Matrix4.h"
#include "math/OBB.h"
#include "math/Plane.h"
#include "math/Ray.h"
#include "math/Sphere.h"
#include "math/Vector3.h"
#include <charconv>
#include <cmath>
#include <cstddef>
#include <iostream>
#include <limits>
#include <sstream>
#include <stdexcept>
#include <string>

namespace {

JsonValue number(double value) {
    if (std::isnan(value)) return "NaN";
    if (std::isinf(value)) return value < 0 ? "-Infinity" : "Infinity";
    if (value == 0 && std::signbit(value)) return "-0";
    return value;
}
JsonValue vectorJSON(const Vector3& value) {
    return JsonValue::Array{number(value.x), number(value.y), number(value.z)};
}
JsonValue matrixJSON(const Matrix3& value) {
    JsonValue::Array elements;
    for (const auto element : value.elements()) elements.push_back(number(element));
    return elements;
}
double parse(const std::string& token) {
    if (token == "NaN") return std::numeric_limits<double>::quiet_NaN();
    if (token == "Infinity") return std::numeric_limits<double>::infinity();
    if (token == "-Infinity") return -std::numeric_limits<double>::infinity();
    if (token == "-0") return -0.;
    double value = 0;
    std::from_chars(token.data(), token.data() + token.size(), value);
    return value;
}

struct Reader {
    std::istringstream stream;
    explicit Reader(const std::string& line) : stream(line) {}
    std::string token() {
        std::string value;
        stream >> value;
        return value;
    }
    double numberToken() { return parse(token()); }
    bool hasMore() {
        stream >> std::ws;
        return stream.peek() != std::char_traits<char>::eof();
    }
    // Component order is fixed by sequential reads; argument evaluation order of a single
    // call expression would not be.
    Vector3 vector() {
        const double x = numberToken();
        const double y = numberToken();
        const double z = numberToken();
        return Vector3(x, y, z);
    }
    Matrix3 rotation() {
        Matrix3 value;
        auto elements = value.elements();
        for (std::size_t i = 0; i < 9; ++i) elements[i] = numberToken();
        return value;
    }
    Matrix4 matrix() {
        Matrix4 value;
        auto elements = value.elements();
        for (std::size_t i = 0; i < 16; ++i) elements[i] = numberToken();
        return value;
    }
};

JsonValue runScenario(const std::string& line) {
    Reader reader(line);
    const std::string kind = reader.token();

    if (kind == "noise") {
        const Vector3 point = reader.vector();
        const ImprovedNoise noise;
        return JsonValue::Object{{"noise", number(noise.noise(point.x, point.y, point.z))}};
    }

    if (kind == "hsv") {
        const double h = reader.numberToken();
        const double s = reader.numberToken();
        const double v = reader.numberToken();
        Color color;
        ColorConverter::setHSV(color, h, s, v);
        return JsonValue::Object{{"rgb", vectorJSON(Vector3(color.r, color.g, color.b))}};
    }

    if (kind == "gethsv") {
        const Vector3 rgb = reader.vector();
        const Color color(rgb.x, rgb.y, rgb.z);
        Vector3 target;
        ColorConverter::getHSV(color, target);
        return JsonValue::Object{{"hsv", vectorJSON(target)}};
    }

    if (kind == "hsvrt") {
        const double h = reader.numberToken();
        const double s = reader.numberToken();
        const double v = reader.numberToken();
        Color color;
        ColorConverter::setHSV(color, h, s, v);
        Vector3 target;
        ColorConverter::getHSV(color, target);
        return JsonValue::Object{{"rgb", vectorJSON(Vector3(color.r, color.g, color.b))},
                                 {"hsv", vectorJSON(target)}};
    }

    if (kind == "hsl") {
        const double h = reader.numberToken();
        const double s = reader.numberToken();
        const double l = reader.numberToken();
        Color color;
        color.setHSL(h, s, l);
        return JsonValue::Object{{"rgb", vectorJSON(Vector3(color.r, color.g, color.b))}};
    }

    if (kind == "gethsl") {
        const Vector3 rgb = reader.vector();
        const Color color(rgb.x, rgb.y, rgb.z);
        Vector3 target;
        color.getHSL(target);
        return JsonValue::Object{{"hsl", vectorJSON(target)}};
    }

    if (kind == "hslrt") {
        const double h = reader.numberToken();
        const double s = reader.numberToken();
        const double l = reader.numberToken();
        Color color;
        color.setHSL(h, s, l);
        Vector3 target;
        color.getHSL(target);
        return JsonValue::Object{{"rgb", vectorJSON(Vector3(color.r, color.g, color.b))},
                                 {"hsl", vectorJSON(target)}};
    }

    if (kind == "capsule-default") {
        const Capsule capsule;
        return JsonValue::Object{{"start", vectorJSON(capsule.start)},
                                 {"end", vectorJSON(capsule.end)},
                                 {"radius", number(capsule.radius)}};
    }

    if (kind == "capsule") {
        const Vector3 start = reader.vector();
        const Vector3 end = reader.vector();
        const double radius = reader.numberToken();
        const Vector3 offset = reader.vector();

        Capsule capsule(start, end, radius);
        const bool setReturnsThis = &capsule.set(start, end, radius) == &capsule;
        Capsule copy;
        copy.copy(capsule);
        Capsule clone = capsule.clone();
        Vector3 center;
        const bool centerReturnsTarget = &capsule.getCenter(center) == &center;
        const bool translateReturnsThis = &clone.translate(offset) == &clone;
        Vector3 translatedCenter;
        clone.getCenter(translatedCenter);

        return JsonValue::Object{
            {"start", vectorJSON(capsule.start)},
            {"end", vectorJSON(capsule.end)},
            {"radius", number(capsule.radius)},
            {"center", vectorJSON(center)},
            {"copyStart", vectorJSON(copy.start)},
            {"copyEnd", vectorJSON(copy.end)},
            {"copyRadius", number(copy.radius)},
            {"cloneStart", vectorJSON(clone.start)},
            {"cloneEnd", vectorJSON(clone.end)},
            {"cloneRadius", number(clone.radius)},
            {"translatedCenter", vectorJSON(translatedCenter)},
            {"sourceStart", vectorJSON(capsule.start)},
            {"sourceEnd", vectorJSON(capsule.end)},
            {"sourceRadius", number(capsule.radius)},
            {"setReturnsThis", setReturnsThis},
            {"centerReturnsTarget", centerReturnsTarget},
            {"translateReturnsThis", translateReturnsThis}};
    }

    if (kind == "capsule-box") {
        const Vector3 start = reader.vector();
        const Vector3 end = reader.vector();
        const double radius = reader.numberToken();
        const Vector3 minimum = reader.vector();
        const Vector3 maximum = reader.vector();
        const Capsule capsule(start, end, radius);
        const Box3 box(minimum, maximum);
        return JsonValue::Object{{"intersects", capsule.intersectsBox(box)}};
    }

    if (kind == "obb-default") {
        const OBB obb;
        return JsonValue::Object{{"center", vectorJSON(obb.center)},
                                 {"halfSize", vectorJSON(obb.halfSize)},
                                 {"rotation", matrixJSON(obb.rotation)}};
    }

    if (kind == "obb") {
        const Vector3 center = reader.vector();
        const Vector3 halfSize = reader.vector();
        const Matrix3 rotation = reader.rotation();

        OBB obb(center, halfSize, rotation);
        Vector3 size;
        const bool sizeReturnsTarget = &obb.getSize(size) == &size;
        OBB clone = obb.clone();
        const bool cloneEquals = clone.equals(obb);
        OBB assigned;
        const bool setReturnsThis = &assigned.set(center, halfSize, rotation) == &assigned;
        const bool setEquals = assigned.equals(obb);
        clone.center.set(123.0, 456.0, 789.0);
        const bool cloneIndependent = !clone.equals(obb) && obb.center.x == center.x &&
                                      obb.center.y == center.y && obb.center.z == center.z;

        return JsonValue::Object{{"center", vectorJSON(obb.center)},
                                 {"halfSize", vectorJSON(obb.halfSize)},
                                 {"rotation", matrixJSON(obb.rotation)},
                                 {"size", vectorJSON(size)},
                                 {"sizeReturnsTarget", sizeReturnsTarget},
                                 {"cloneEquals", cloneEquals},
                                 {"cloneIndependent", cloneIndependent},
                                 {"setReturnsThis", setReturnsThis},
                                 {"setEquals", setEquals}};
    }

    if (kind == "obb-apply") {
        const Vector3 center = reader.vector();
        const Vector3 halfSize = reader.vector();
        const Matrix3 rotation = reader.rotation();
        const Matrix4 matrix = reader.matrix();

        OBB obb(center, halfSize, rotation);
        const bool returnsThis = &obb.applyMatrix4(matrix) == &obb;
        return JsonValue::Object{{"center", vectorJSON(obb.center)},
                                 {"halfSize", vectorJSON(obb.halfSize)},
                                 {"rotation", matrixJSON(obb.rotation)},
                                 {"returnsThis", returnsThis}};
    }

    if (kind == "obb-contains") {
        const Vector3 center = reader.vector();
        const Vector3 halfSize = reader.vector();
        const Matrix3 rotation = reader.rotation();
        const Vector3 point = reader.vector();
        const OBB obb(center, halfSize, rotation);
        return JsonValue::Object{{"contains", obb.containsPoint(point)}};
    }

    if (kind == "obb-clamp") {
        const Vector3 center = reader.vector();
        const Vector3 halfSize = reader.vector();
        const Matrix3 rotation = reader.rotation();
        const Vector3 point = reader.vector();
        const OBB obb(center, halfSize, rotation);
        Vector3 target;
        const bool targetReturned = &obb.clampPoint(point, target) == &target;
        return JsonValue::Object{{"point", vectorJSON(target)}, {"targetReturned", targetReturned}};
    }

    if (kind == "obb-box3") {
        const Vector3 center = reader.vector();
        const Vector3 halfSize = reader.vector();
        const Matrix3 rotation = reader.rotation();
        const Vector3 minimum = reader.vector();
        const Vector3 maximum = reader.vector();
        const OBB obb(center, halfSize, rotation);
        const Box3 box(minimum, maximum);
        return JsonValue::Object{{"intersects", obb.intersectsBox3(box)}};
    }

    if (kind == "obb-sphere") {
        const Vector3 center = reader.vector();
        const Vector3 halfSize = reader.vector();
        const Matrix3 rotation = reader.rotation();
        const Vector3 sphereCenter = reader.vector();
        const double radius = reader.numberToken();
        const OBB obb(center, halfSize, rotation);
        const Sphere sphere(sphereCenter, radius);
        return JsonValue::Object{{"intersects", obb.intersectsSphere(sphere)}};
    }

    if (kind == "obb-ray") {
        const Vector3 center = reader.vector();
        const Vector3 halfSize = reader.vector();
        const Matrix3 rotation = reader.rotation();
        const Vector3 origin = reader.vector();
        const Vector3 direction = reader.vector();
        const OBB obb(center, halfSize, rotation);
        const Ray ray(origin, direction);
        Vector3 target;
        Vector3* hit = obb.intersectRay(ray, target);
        return JsonValue::Object{{"hit", hit != nullptr},
                                 {"point", hit != nullptr ? vectorJSON(target) : JsonValue(nullptr)},
                                 {"intersects", obb.intersectsRay(ray)}};
    }

    if (kind == "obb-obb") {
        const Vector3 center = reader.vector();
        const Vector3 halfSize = reader.vector();
        const Matrix3 rotation = reader.rotation();
        const Vector3 otherCenter = reader.vector();
        const Vector3 otherHalfSize = reader.vector();
        const Matrix3 otherRotation = reader.rotation();
        const bool withEpsilon = reader.hasMore();
        const double epsilon = withEpsilon ? reader.numberToken() : 0;
        const OBB a(center, halfSize, rotation);
        const OBB b(otherCenter, otherHalfSize, otherRotation);
        // Without a token the C++ default argument (Number.EPSILON) is the one under test.
        const bool intersects = withEpsilon ? a.intersectsOBB(b, epsilon) : a.intersectsOBB(b);
        return JsonValue::Object{{"intersects", intersects}};
    }

    if (kind == "obb-plane") {
        const Vector3 center = reader.vector();
        const Vector3 halfSize = reader.vector();
        const Matrix3 rotation = reader.rotation();
        const Vector3 normal = reader.vector();
        const double constant = reader.numberToken();
        const OBB obb(center, halfSize, rotation);
        const Plane plane(normal, constant);
        return JsonValue::Object{{"intersects", obb.intersectsPlane(plane)}};
    }

    if (kind == "obb-frombox") {
        const Vector3 minimum = reader.vector();
        const Vector3 maximum = reader.vector();
        const Box3 box(minimum, maximum);
        OBB obb(Vector3(9.0, 9.0, 9.0), Vector3(9.0, 9.0, 9.0), Matrix3(0, 1, 0, -1, 0, 0, 0, 0, 1));
        const bool returnsThis = &obb.fromBox3(box) == &obb;
        return JsonValue::Object{{"center", vectorJSON(obb.center)},
                                 {"halfSize", vectorJSON(obb.halfSize)},
                                 {"rotation", matrixJSON(obb.rotation)},
                                 {"returnsThis", returnsThis}};
    }

    if (kind == "obb-equals") {
        const Vector3 center = reader.vector();
        const Vector3 halfSize = reader.vector();
        const Matrix3 rotation = reader.rotation();
        const Vector3 otherCenter = reader.vector();
        const Vector3 otherHalfSize = reader.vector();
        const Matrix3 otherRotation = reader.rotation();
        const OBB a(center, halfSize, rotation);
        const OBB b(otherCenter, otherHalfSize, otherRotation);
        return JsonValue::Object{{"equals", a.equals(b)}, {"reversed", b.equals(a)}};
    }

    throw std::runtime_error("unknown scenario kind: " + kind);
}

} // namespace

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        if (line.empty()) continue;
        try {
            std::cout << runScenario(line).dump() << '\n';
        } catch (const std::exception& error) {
            std::cout << JsonValue(JsonValue::Object{{"probeError", error.what()}}).dump() << '\n';
        }
    }
    return 0;
}
